@Tags(['slow'])
library;

import 'dart:async';
import 'dart:math';

import 'package:harbor/harbor.dart';
import 'package:rohd/rohd.dart';
import 'package:test/test.dart';

// Goldens captured from the bit-exact software decoder's inverse transform are
// embedded at the end (keyed by '${txSize}_$txType', one residual per block).
const _wide = [
  4,
  8,
  16,
  32,
  64,
  4,
  8,
  8,
  16,
  16,
  32,
  32,
  64,
  4,
  16,
  8,
  32,
  16,
  64,
];
const _high = [
  4,
  8,
  16,
  32,
  64,
  8,
  4,
  16,
  8,
  32,
  16,
  64,
  32,
  16,
  4,
  32,
  8,
  64,
  16,
];
const _names = [
  'TX_4X4',
  'TX_8X8',
  'TX_16X16',
  'TX_32X32',
  'TX_64X64',
  'TX_4X8',
  'TX_8X4',
  'TX_8X16',
  'TX_16X8',
  'TX_16X32',
  'TX_32X16',
  'TX_32X64',
  'TX_64X32',
  'TX_4X16',
  'TX_16X4',
  'TX_8X32',
  'TX_32X8',
  'TX_16X64',
  'TX_64X16',
];

void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  BigInt pack(List<int> c) {
    var v = BigInt.zero;
    for (var i = 0; i < c.length; i++) {
      v |= BigInt.from(c[i] & 0xFFFF) << (i * 16);
    }
    return v;
  }

  List<int> unpack(BigInt v, int n) => [
    for (var i = 0; i < n; i++)
      (() {
        final raw = ((v >> (i * 16)) & BigInt.from(0xFFFF)).toInt();
        return raw >= 0x8000 ? raw - 0x10000 : raw;
      })(),
  ];

  for (var txSize = 0; txSize < 19; txSize++) {
    final txw = _wide[txSize];
    final txh = _high[txSize];
    final n = txw * txh;
    final numBlocks = n <= 256 ? 5 : (n <= 1024 ? 3 : 2);

    for (var txType = 0; txType < 16; txType++) {
      // Skip (size, type) combinations the spec does not define.
      final key = '${txSize}_$txType';
      if (!_goldenInv.containsKey(key)) continue;

      test('HarborInvTxfm ${_names[txSize]} txType=$txType', () async {
        final t = HarborInvTxfm(txSize: txSize, txType: txType);
        final clk = SimpleClockGenerator(10).clk;
        final reset = Logic(name: 'reset');
        final start = Logic(name: 'start');
        final coeffs = Logic(name: 'coeffs', width: n * 16);
        t.input('clk').srcConnection! <= clk;
        t.input('reset').srcConnection! <= reset;
        t.input('start').srcConnection! <= start;
        t.input('coeffs').srcConnection! <= coeffs;
        await t.build();
        reset.inject(1);
        start.inject(0);
        coeffs.inject(0);
        Simulator.setMaxSimTime(500000000);
        unawaited(Simulator.run());
        await clk.nextPosedge;
        reset.inject(0);
        await clk.nextPosedge;

        final rng = Random(0x5A1 + txSize * 16 + txType);
        final blocks = <(String, List<int>)>[
          ('dc only', [200, ...List.filled(n - 1, 0)]),
          if (numBlocks >= 3)
            (
              'sparse',
              [for (var i = 0; i < n; i++) (i % 5 == 0) ? (i * 3 - 30) : 0],
            ),
          if (numBlocks >= 5)
            ('ramp', [for (var i = 0; i < n; i++) (i * 7 - n * 3)]),
          ('random a', [for (var i = 0; i < n; i++) rng.nextInt(1024) - 512]),
          if (numBlocks >= 3)
            (
              'random b',
              [for (var i = 0; i < n; i++) rng.nextInt(2048) - 1024],
            ),
        ];

        for (var bi = 0; bi < blocks.length; bi++) {
          final b = blocks[bi];
          coeffs.inject(pack(b.$2));
          start.inject(1);
          await clk.nextPosedge;
          start.inject(0);
          // Wait for done (latency ~ txh + txw + a couple cycles).
          var guard = 0;
          while (t.output('done').value.toInt() != 1) {
            await clk.nextPosedge;
            if (++guard > txw + txh + 16) {
              fail(
                'timeout waiting for done: ${_names[txSize]} $txType ${b.$1}',
              );
            }
          }
          final got = unpack(t.output('residual').value.toBigInt(), n);
          final want = _goldenInv[key]![bi];
          expect(
            got,
            equals(want),
            reason: '${_names[txSize]} txType=$txType ${b.$1}',
          );
          // Return to idle before the next vector.
          await clk.nextPosedge;
        }
        await Simulator.endSimulation();
      });
    }
  }
}

